node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('SELECT * FROM \"' + t.name + '\" LIMIT 1').columns().map(c => c.name);
  for (const col of cols) {
    try {
      const rows = db.prepare('SELECT * FROM \"' + t.name + '\" WHERE \"' + col + '\" LIKE ?').all('%Daniel Ortiz%');
      if (rows.length) {
        console.log('\nFound in table \"' + t.name + '\", column \"' + col + '\":');
        rows.forEach(r => console.log(r));
      }
    } catch(e) {}
  }
}
db.close();
" 2>&1 || echo "--- better-sqlite3 not available, trying strings ---"; strings /workspace/world.db | grep -i "Daniel Ortiz"

npm install better-sqlite3 --prefix /tmp/sq 2>&1 | tail -3; node -e "
const Database = require('/tmp/sq/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.pragma('table_info(' + t.name + ')');
  const textCols = info.filter(c => ['TEXT','VARCHAR','CHAR'].some(x => (c.type||'').toUpperCase().includes(x))).map(c => c.name);
  for (const col of textCols) {
    const rows = db.prepare('SELECT * FROM \"' + t.name + '\" WHERE \"' + col + '\" LIKE ?').all('%Daniel Ortiz%');
    if (rows.length) {
      console.log('\n=== Found in table \"' + t.name + '\" ===');
      rows.forEach(r => { for (const [k,v] of Object.entries(r)) console.log('  ' + k + ': ' + v); });
    }
  }
}
db.close();
"
